type RateLimitEntry = {
  count: number;
  resetAt: number;
};

const store = new Map<string, RateLimitEntry>();

const WINDOW_MS = 60_000;
const MAX = 20;
const MAX_ENTRIES = 10_000;

let lastPrune = 0;

function prune() {
  const now = Date.now();
  if (now - lastPrune < 60_000) return;
  lastPrune = now;
  for (const [key, entry] of store) {
    if (entry.resetAt <= now) store.delete(key);
  }
}

export function rateLimit(
  key: string,
  limit = MAX,
  windowMs = WINDOW_MS
): { ok: boolean; remaining: number; retryAfter: number } {
  prune();
  const now = Date.now();
  const entry = store.get(key);

  if (!entry || entry.resetAt <= now) {
    if (store.size >= MAX_ENTRIES) {
      for (const [k] of store) {
        store.delete(k);
        if (store.size < MAX_ENTRIES) break;
      }
    }
    store.set(key, { count: 1, resetAt: now + windowMs });
    return { ok: true, remaining: limit - 1, retryAfter: 0 };
  }

  if (entry.count >= limit) {
    return { ok: false, remaining: 0, retryAfter: Math.ceil((entry.resetAt - now) / 1000) };
  }

  entry.count += 1;
  return { ok: true, remaining: limit - entry.count, retryAfter: 0 };
}

export function rateLimitByIp(
  ip: string,
  limit?: number,
  windowMs?: number
): { ok: boolean; remaining: number; retryAfter: number } {
  return rateLimit(`ip:${ip}`, limit, windowMs);
}

export function getClientIp(request: Request): string {
  const xff = request.headers.get("x-forwarded-for");
  if (xff) return xff.split(",")[0].trim();
  return "unknown";
}

// ---------------------------------------------------------------------------
// Login attempt lockout: max 3 failed attempts within the window, then lock.
// ---------------------------------------------------------------------------

type LoginEntry = {
  failures: number;
  windowStart: number;
  lockedUntil: number;
};

const loginStore = new Map<string, LoginEntry>();
const LOGIN_MAX = 3;
const LOGIN_WINDOW_MS = 30 * 60_000;

function pruneLogins() {
  const now = Date.now();
  for (const [key, entry] of loginStore) {
    if (entry.windowStart + LOGIN_WINDOW_MS <= now && entry.lockedUntil <= now) {
      loginStore.delete(key);
    }
  }
}

export function getLoginStatus(email: string): {
  locked: boolean;
  retryAfter: number;
  remaining: number;
} {
  pruneLogins();
  const now = Date.now();
  const entry = loginStore.get(email.toLowerCase());
  if (!entry || entry.windowStart + LOGIN_WINDOW_MS <= now) {
    return { locked: false, retryAfter: 0, remaining: LOGIN_MAX };
  }
  if (entry.lockedUntil > now) {
    return {
      locked: true,
      retryAfter: Math.ceil((entry.lockedUntil - now) / 1000),
      remaining: 0,
    };
  }
  return { locked: false, retryAfter: 0, remaining: LOGIN_MAX - entry.failures };
}

export function registerLoginFailure(email: string): void {
  pruneLogins();
  const now = Date.now();
  const key = email.toLowerCase();
  const entry = loginStore.get(key);
  if (!entry || entry.windowStart + LOGIN_WINDOW_MS <= now) {
    loginStore.set(key, { failures: 1, windowStart: now, lockedUntil: 0 });
    return;
  }
  entry.failures += 1;
  if (entry.failures >= LOGIN_MAX) {
    entry.lockedUntil = now + LOGIN_WINDOW_MS;
  }
}

export function clearLoginFailures(email: string): void {
  loginStore.delete(email.toLowerCase());
}
